import { describe, it, expect } from "vitest"
import { MessageOpcode, ProtocolCodec, type ProtocolMessage } from "./protocol"

const ALL_OPCODES: MessageOpcode[] = [
  MessageOpcode.CONNECT,
  MessageOpcode.DISCONNECT,
  MessageOpcode.PING,
  MessageOpcode.PONG,
  MessageOpcode.DATA,
  MessageOpcode.ACK,
  MessageOpcode.NACK,
  MessageOpcode.ERROR,
]

function roundTrip(msg: ProtocolMessage): ProtocolMessage {
  return ProtocolCodec.decode(ProtocolCodec.encode(msg))
}

describe("ProtocolCodec", () => {
  it("encodes and decodes round-trips for every opcode", () => {
    for (const opcode of ALL_OPCODES) {
      const msg: ProtocolMessage = {
        version: 1,
        opcode,
        sequenceId: 42,
        payload: Buffer.from([0xde, 0xad, 0xbe, 0xef]),
      }

      const decoded = roundTrip(msg)

      expect(decoded.opcode).toBe(opcode)
      expect(decoded.version).toBe(1)
      expect(decoded.sequenceId).toBe(42)
      expect(decoded.payload.equals(msg.payload)).toBe(true)
    }
  })

  it("round-trips an empty payload", () => {
    const msg: ProtocolMessage = {
      version: 1,
      opcode: MessageOpcode.PING,
      sequenceId: 7,
      payload: Buffer.alloc(0),
    }

    const encoded = ProtocolCodec.encode(msg)
    expect(encoded.length).toBe(ProtocolCodec.HEADER_SIZE)

    const decoded = roundTrip(msg)
    expect(decoded.payload.length).toBe(0)
    expect(decoded.opcode).toBe(MessageOpcode.PING)
    expect(decoded.sequenceId).toBe(7)
    expect(decoded.version).toBe(1)
  })

  it("round-trips a small text payload", () => {
    const payload = Buffer.from("hello protocol", "utf8")
    const msg: ProtocolMessage = {
      version: 1,
      opcode: MessageOpcode.DATA,
      sequenceId: 123,
      payload,
    }

    const encoded = ProtocolCodec.encode(msg)
    expect(encoded.length).toBe(ProtocolCodec.HEADER_SIZE + payload.length)

    const decoded = roundTrip(msg)
    expect(decoded.payload.toString("utf8")).toBe("hello protocol")
    expect(decoded.opcode).toBe(MessageOpcode.DATA)
    expect(decoded.sequenceId).toBe(123)
  })

  it("round-trips a 4KB binary payload without corruption", () => {
    const payload = Buffer.alloc(4096)
    for (let i = 0; i < payload.length; i++) {
      payload[i] = (i * 31 + 7) & 0xff
    }

    const msg: ProtocolMessage = {
      version: 1,
      opcode: MessageOpcode.DATA,
      sequenceId: 0x1020304,
      payload,
    }

    const encoded = ProtocolCodec.encode(msg)
    expect(encoded.length).toBe(ProtocolCodec.HEADER_SIZE + 4096)

    const decoded = roundTrip(msg)
    expect(decoded.payload.length).toBe(4096)
    expect(decoded.payload.equals(payload)).toBe(true)
  })

  it("round-trips a 4KB random binary payload byte-for-byte", () => {
    const payload = Buffer.alloc(4096)
    for (let i = 0; i < payload.length; i++) {
      payload[i] = Math.floor(Math.random() * 256)
    }

    const decoded = roundTrip({
      version: 1,
      opcode: MessageOpcode.DATA,
      sequenceId: 99,
      payload,
    })

    expect(decoded.payload.equals(payload)).toBe(true)
  })

  it("produces an exact wire format: magic, version, opcode, reserved, sequenceId, payload", () => {
    const payload = Buffer.from([0x01, 0x02, 0x03])
    const encoded = ProtocolCodec.encode({
      version: 2,
      opcode: MessageOpcode.ACK,
      sequenceId: 0x0a0b0c0d,
      payload,
    })

    expect(encoded.length).toBe(11)
    expect(encoded.readUInt8(0)).toBe(ProtocolCodec.MAGIC_BYTE)
    expect(encoded.readUInt8(1)).toBe(2)
    expect(encoded.readUInt8(2)).toBe(MessageOpcode.ACK)
    expect(encoded.readUInt8(3)).toBe(0) // Reserved
    expect(encoded.readUInt32BE(4)).toBe(0x0a0b0c0d)
    expect(encoded.subarray(8).equals(payload)).toBe(true)
  })

  it("accepts a buffer with a valid magic byte", () => {
    const buf = Buffer.alloc(ProtocolCodec.HEADER_SIZE)
    buf.writeUInt8(ProtocolCodec.MAGIC_BYTE, 0)
    buf.writeUInt8(1, 1)
    buf.writeUInt8(MessageOpcode.PONG, 2)
    buf.writeUInt32BE(5, 4)

    const decoded = ProtocolCodec.decode(buf)
    expect(decoded.version).toBe(1)
    expect(decoded.opcode).toBe(MessageOpcode.PONG)
    expect(decoded.sequenceId).toBe(5)
    expect(decoded.payload.length).toBe(0)
  })

  it("throws an error when the magic byte is invalid", () => {
    const buf = Buffer.alloc(ProtocolCodec.HEADER_SIZE)
    buf.writeUInt8(0x00, 0) // Wrong magic
    buf.writeUInt8(1, 1)
    buf.writeUInt8(MessageOpcode.DATA, 2)
    buf.writeUInt32BE(1, 4)

    expect(() => ProtocolCodec.decode(buf)).toThrow(/Invalid magic byte/)
    expect(() => ProtocolCodec.decode(buf)).toThrow(/00/)
  })

  it("throws for every possible wrong magic byte value", () => {
    for (let magic = 0; magic <= 0xff; magic++) {
      if (magic === ProtocolCodec.MAGIC_BYTE) continue

      const buf = Buffer.alloc(ProtocolCodec.HEADER_SIZE)
      buf.writeUInt8(magic, 0)
      buf.writeUInt8(1, 1)
      buf.writeUInt8(MessageOpcode.PING, 2)
      buf.writeUInt32BE(0, 4)

      expect(() => ProtocolCodec.decode(buf)).toThrow(/Invalid magic byte/)
    }
  })

  it("throws on a buffer shorter than the 8-byte header (underflow)", () => {
    const buf = Buffer.from([ProtocolCodec.MAGIC_BYTE, 0x01, 0x03, 0x00, 0x00, 0x00, 0x00])

    expect(buf.length).toBeLessThan(ProtocolCodec.HEADER_SIZE)
    expect(() => ProtocolCodec.decode(buf)).toThrow(/Buffer too short/)
  })

  it("throws on every header length from 0 to 7 (underflow boundary)", () => {
    for (let len = 0; len < ProtocolCodec.HEADER_SIZE; len++) {
      const buf = Buffer.alloc(len, ProtocolCodec.MAGIC_BYTE)
      expect(() => ProtocolCodec.decode(buf)).toThrow(/Buffer too short for protocol header/)
    }
  })

  it("preserves sequenceId across the full 32-bit unsigned integer range", () => {
    const sequenceIds = [
      0,
      1,
      0x0000ffff,
      0x00010000,
      0x7fffffff,
      0x80000000,
      0xfffffffe,
      0xffffffff,
    ]

    for (const sequenceId of sequenceIds) {
      const decoded = roundTrip({
        version: 1,
        opcode: MessageOpcode.DATA,
        sequenceId,
        payload: Buffer.from("seq"),
      })

      expect(decoded.sequenceId).toBe(sequenceId)
    }
  })

  it("preserves sequenceId at the extremes 0 and 4294967295", () => {
    expect(0xffffffff).toBe(4294967295)

    const decodedMin = roundTrip({
      version: 1,
      opcode: MessageOpcode.DATA,
      sequenceId: 0,
      payload: Buffer.alloc(0),
    })
    expect(decodedMin.sequenceId).toBe(0)

    const decodedMax = roundTrip({
      version: 1,
      opcode: MessageOpcode.DATA,
      sequenceId: 4294967295,
      payload: Buffer.alloc(0),
    })
    expect(decodedMax.sequenceId).toBe(4294967295)
  })

  it("preserves sequenceId 4294967295 as unsigned (not negative)", () => {
    const encoded = ProtocolCodec.encode({
      version: 1,
      opcode: MessageOpcode.NACK,
      sequenceId: 4294967295,
      payload: Buffer.alloc(0),
    })

    expect(encoded.readUInt32BE(4)).toBe(4294967295)
    expect(ProtocolCodec.decode(encoded).sequenceId).toBeGreaterThan(0)
  })

  it("keeps payloads independent of the source buffer after encoding", () => {
    const payload = Buffer.from([1, 2, 3, 4])
    const encoded = ProtocolCodec.encode({
      version: 1,
      opcode: MessageOpcode.ERROR,
      sequenceId: 9,
      payload,
    })

    payload.fill(0xff) // Mutate the source after encoding

    const decoded = ProtocolCodec.decode(encoded)
    expect(decoded.payload.equals(Buffer.from([1, 2, 3, 4]))).toBe(true)
  })

  it("rejects a NACK/ERROR encoded frame only when magic is corrupted", () => {
    const msg: ProtocolMessage = {
      version: 1,
      opcode: MessageOpcode.ERROR,
      sequenceId: 77,
      payload: Buffer.from("boom"),
    }
    const encoded = ProtocolCodec.encode(msg)

    // Corrupt the magic byte in a copy.
    const corrupted = Buffer.from(encoded)
    corrupted[0] = ProtocolCodec.MAGIC_BYTE ^ 0xff

    expect(() => ProtocolCodec.decode(corrupted)).toThrow(/Invalid magic byte/)

    // Original untouched frame still decodes fine.
    const decoded = ProtocolCodec.decode(encoded)
    expect(decoded.opcode).toBe(MessageOpcode.ERROR)
    expect(decoded.payload.toString("utf8")).toBe("boom")
  })
})
